#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Buf { char *p; size_t n; };

int main(void) {
    struct Buf a;
    a.p = malloc(4);
    a.n = 4;
    strcpy(a.p, "hi");
    struct Buf b = a;          /* 浅拷贝：b.p 与 a.p 相同 */
    printf("before: a=\"%s\" b=\"%s\"\n", a.p, b.p);
    b.p[0] = 'X';              /* 改 b 影响 a，因为共享 */
    printf("after:  a=\"%s\" (被 b 的写入影响)\n", a.p);
    free(a.p);
    return 0;
}
